use leptos::html::{Div, div};
use leptos::prelude::*;
use leptos_ui::tw_merge::tw_merge;
use leptos_use::use_resize_observer;
use models::cal::time_cells::common::Cell;
use reactive_stores::StoreField;

/// Defines the rendering interface for a calendar graph.
///
/// A calendar graph consists of three rendering layers:
///
/// 1. Background: Defines the graph's background and its table geometry.
/// 2. Table: Renders the calendar cells and provides their associated time labels.
/// 3. Overlay: Renders additional visual elements on top of the table using
///    the time labels generated by the table.
///
/// # Type Parameters
///
/// - `S`: The reactive store field type associated with the calendar cell.
///   Must implement [`StoreField`] with [`Value`](StoreField::Value) equal to `C`,
///   and be [`Copy`].
/// - `C`: The calendar time cell type. Must implement [`Cell`].
/// - `T`: The time representation associated with the calendar cells.
///   Must implement [`Send`], [`Sync`], and have a `'static` lifetime.
///
/// # Rendering Pipeline
///
/// The rendering process is expected to follow this order:
///
/// 1. Call [`draw_bg`](Self::draw_bg) to obtain the background view and table geometry.
/// 2. Pass the resulting geometry to [`draw_table`](Self::draw_table).
/// 3. Pass the generated point labels and table geometry to
///    [`draw_overlay`](Self::draw_overlay).
///
/// # Implementation Notes
///
/// Implementations are responsible for maintaining consistent coordinate systems
/// between the table and overlay layers. The overlay must interpret normalized
/// positions relative to the reference area defined by the graph geometry.
pub trait CalGraphDraw<S, C, T>
where
    S: StoreField<Value = C> + Copy,
    C: Cell,
    T: Send + Sync + 'static,
{
    /// Creates the calendar graph view.
    ///
    /// This method provides the entry point for rendering a calendar graph.
    ///
    /// # Returns
    ///
    /// A view representing the calendar graph.
    fn draw(&self, class: String) -> impl IntoView {
        let parent_ref = NodeRef::<Div>::new();
        let size = make_react(parent_ref);

        let (bg, table_geo) = self.draw_bg(&size);
        let (table, labels) = self.draw_table(&table_geo);
        let overlay = self.draw_overlay(&size, &table_geo, labels);

        div()
            .node_ref(parent_ref)
            .class(tw_merge!("grid", class))
            .child((bg, table, overlay))
    }

    /// Renders the graph background and calculates the table geometry.
    ///
    /// The returned geometry describes the table's position and dimensions
    /// within the graph.
    ///
    /// # Arguments
    ///
    /// - `size`: The available dimensions of the graph.
    ///
    /// # Returns
    ///
    /// A tuple containing:
    /// - The background view.
    /// - The geometry required to position and size the calendar table.
    fn draw_bg(&self, size: &Size) -> (impl IntoView, TableGeo);

    /// Renders the calendar table using the supplied geometry.
    ///
    /// The resulting point labels associate positions within the table
    /// with their corresponding time values. These labels can be consumed
    /// by the overlay layer.
    ///
    /// # Arguments
    ///
    /// - `table_geo`: The position and dimensions of the table.
    ///
    /// # Returns
    ///
    /// A tuple containing:
    /// - The rendered table view.
    /// - A reactive signal containing the table's point labels.
    fn draw_table(&self, table_geo: &TableGeo) -> (impl IntoView, Signal<Vec<PointLabel<T>>>);

    /// Renders additional visual elements over the calendar graph.
    ///
    /// The overlay uses the table geometry and associated point labels
    /// to position visual elements relative to the calendar table.
    ///
    /// # Arguments
    ///
    /// - `size`: The available dimensions of the graph.
    /// - `table_geo`: The position and dimensions of the calendar table.
    /// - `point_labels`: A reactive signal containing the table's point labels.
    ///
    /// # Returns
    ///
    /// A view containing the overlay elements.
    fn draw_overlay(
        &self,
        size: &Size,
        table_geo: &TableGeo,
        point_labels: Signal<Vec<PointLabel<T>>>,
    ) -> impl IntoView;
}

/// Represents the available dimensions of a calendar graph.
///
/// Both dimensions are reactive signals, allowing the graph to respond
/// to changes in its container size.
pub struct Size {
    /// The available width in pixels.
    pub width: Signal<u32>,

    /// The available height in pixels.
    pub height: Signal<u32>,
}

/// Represents a two-dimensional offset in pixels.
///
/// The origin `(0, 0)` corresponds to the top-left corner of the
/// reference coordinate system.
pub struct Offset {
    /// The horizontal offset in pixels.
    pub x: u32,

    /// The vertical offset in pixels.
    pub y: u32,
}

/// Describes the position and dimensions of the calendar table
/// within its containing graph.
///
/// The offset and size define the table's bounding rectangle.
pub struct TableGeo {
    /// The table's top-left position relative to the graph origin.
    pub offset: Offset,

    /// The table's dimensions.
    pub size: Size,
}

/// Represents a normalized two-dimensional position relative to a reference area.
///
/// Both coordinates are expected to be within the inclusive range `[0.0, 1.0]`.
///
/// The coordinate system uses the top-left corner as its origin:
///
/// - `(0.0, 0.0)` represents the top-left corner.
/// - `(1.0, 0.0)` represents the top-right corner.
/// - `(0.0, 1.0)` represents the bottom-left corner.
/// - `(1.0, 1.0)` represents the bottom-right corner.
///
/// Coordinates are represented as reactive signals, allowing the position
/// to change dynamically without requiring the containing structure to be
/// recreated.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RelativeLocation {
    /// The normalized horizontal coordinate.
    pub x: Signal<f32>,

    /// The normalized vertical coordinate.
    pub y: Signal<f32>,
}

/// Associates a normalized position within a calendar graph with a time value.
///
/// A point label provides the spatial and temporal information required
/// by overlay elements to locate and interpret positions within the calendar.
///
/// # Type Parameters
///
/// - `T`: The time representation associated with this point.
///   Must implement [`Send`], [`Sync`], and have a `'static` lifetime.
pub struct PointLabel<T>
where
    T: Send + Sync + 'static,
{
    /// The normalized position of the point relative to its reference area.
    pub loc: RelativeLocation,

    /// The time value associated with this position.
    pub time: T,
}

fn make_react(parent_ref: NodeRef<Div>) -> Size {
    let (width, set_width) = signal(1);
    use_resize_observer(parent_ref, move |entries, _| {
        let rect = entries[0].content_rect();
        set_width.set(rect.width() as u32);
    });

    let (height, set_height) = signal(1);
    use_resize_observer(parent_ref, move |entries, _| {
        let rect = entries[0].content_rect();
        set_height.set(rect.height() as u32);
    });

    Size {
        width: width.into(),
        height: height.into(),
    }
}
